class Solution:
    def jobScheduling(self, startTime: list[int], endTime: list[int], profit: list[int]) -> int:
        jobs = sorted(zip(startTime, endTime, profit))
        n = len(jobs)
        def dfs(i: int) -> int:
            if i == n:
                return 0
            j = i + 1
            while j < n and jobs[j][0] < jobs[i][1]:
                j += 1
            return max(dfs(i + 1), jobs[i][2] + dfs(j))
        return dfs(0)

